import{c as a,Q as t,j as o,m as n}from"./chunks/framework.B5EQ7QKW.js";const r="/thalamus/main/backends-native.svg",m=JSON.parse('{"title":"Native Backend","description":"","frontmatter":{"title":"Native Backend"},"headers":[],"relativePath":"concepts/backends/native/index.md","filePath":"concepts/backends/native/index.md","lastUpdated":1790343418000}'),c={name:"concepts/backends/native/index.md"};function d(i,e,s,l,h,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="native-backend" tabindex="-1">Native backend <a class="header-anchor" href="#native-backend" aria-label="Permalink to &quot;Native backend&quot;">​</a></h1><p>The native backend is Thalamus&#39; built-in serving backend and the default for every <a href="/thalamus/main/reference/model-crd-api"><code>Model</code></a>. The Thalamus operator reconciles each <code>Model</code> custom resource (<code>thalamus.cloud/v1alpha1</code>) into a complete per-model runtime, served behind a shared Gateway API gateway backed by <a href="https://agentgateway.dev/" target="_blank" rel="noreferrer">agentgateway</a>.</p><p><img src="'+r+'" alt="Native backend architecture"></p><h2 id="reconciliation" tabindex="-1">Reconciliation <a class="header-anchor" href="#reconciliation" aria-label="Permalink to &quot;Reconciliation&quot;">​</a></h2><p>The operator watches <code>Model</code> resources and reconciles each one into:</p><ul><li><strong>Engine</strong> — a vLLM <code>Deployment</code> and <code>Service</code> that serve the model.</li><li><strong>Endpoint Picker (EPP)</strong> — an llm-d deployment that selects the best engine replica for each request, scored on live signals such as KV-cache utilization, queue depth, and prefix-cache affinity.</li><li><strong>InferencePool</strong> — the Gateway API Inference Extension resource that ties the EPP to the model&#39;s engine pods.</li><li><strong>Routing</strong> — a per-model <code>HTTPRoute</code> and <code>AgentgatewayBackend</code> that attach the model to the inference gateway.</li></ul><p>The operator also keeps a model-list <code>AgentgatewayPolicy</code> in sync, so the <code>/v1/models</code> endpoint always reflects the models that are currently <code>Ready</code> in each namespace.</p><h2 id="gateway" tabindex="-1">Gateway <a class="header-anchor" href="#gateway" aria-label="Permalink to &quot;Gateway&quot;">​</a></h2><p>The shared inference gateway is a plain Gateway API gateway, backed by agentgateway. A body-based routing <code>AgentgatewayPolicy</code> extracts the model name from each request body and sets the Inference Extension&#39;s <code>X-Gateway-Base-Model-Name</code> header, which the per-model <code>HTTPRoute</code> matches to route the request to the right model. See <a href="/thalamus/main/concepts/backends/native/request-flow">Request flow</a> for a step-by-step walkthrough.</p><h2 id="artifacts-and-infrastructure" tabindex="-1">Artifacts and infrastructure <a class="header-anchor" href="#artifacts-and-infrastructure" aria-label="Permalink to &quot;Artifacts and infrastructure&quot;">​</a></h2><p>The <code>Model</code> deployments in Thalamus depend on additional infrastructure that needs to be provided by cluster administrators. The container images are pulled from an OCI registry and the model weights are fetched from an object store. The reconciled workloads run on GPU nodes prepared by the vendor GPU operators (NVIDIA, AMD, Intel), and metrics collected by Prometheus and OpenTelemetry.</p>',11)])])}const f=a(c,[["render",d]]);export{m as __pageData,f as default};
